// Unmodified broadcaster logos, downloaded 2026-11-12. Sources and trademark attribution: docs/RADIO-SOURCES.md.
export const RADIO_LOGOS = {"qmusic": "data:image/png;base64,", "q90": "data:image/png;base64,", "radio538": "data:image/png;base64,", "sky": "data:image/png;base64,", "veronica": "data:image/webp;base64,", "npo": "data:image/png;base64,"};
const bundled = new Set(Object.values(RADIO_LOGOS));
export function isBundledRadioLogo(value: string) { return bundled.has(value); }
